            for j, b in enumerate(blocks):
                for i in range(1, b):
                    can_move = True
                    new_blocks = list(blocks)
                    new_blocks.pop(j)
                    if i-1 > 0: new_blocks.append(i-1)
                    if b-i-1 > 0: new_blocks.append(b-i-1)
                    res = max(res, solve(tuple(new_blocks), False))
            if not can_move:
                res = sum(blocks)
            memo_U[(blocks, True)] = res
            return res
        else:
            if (blocks, False) in memo_V: return memo_V[(blocks, False)]
            res = float('inf')
            can_move = False
            for j, b in enumerate(blocks):
                for i in range(1, b):
