def solve_scoring_impartial(n_max):
    memo_f = {}
    memo_g = {}

    def get_value(segments, is_alice_turn):
        segments = tuple(sorted([s for s in segments if s > 0]))
        if not segments:
            return 0
        if all(s == 1 for s in segments):
            return len(segments)

        if is_alice_turn:
            if segments in memo_f: return memo_f[segments]
        else:
            if segments in memo_g: return memo_g[segments]

        res = None
        # Try all moves
        for idx, n in enumerate(segments):
            if n > 1:
                for i in range(1, n):
                    new_segments = list(segments)
                    new_segments.pop(idx)
                    new_segments.append(i-1)
                    new_segments.append(n-i-1)

                    val = get_value(tuple(new_segments), not is_alice_turn)
                    if is_alice_turn:
                        if res is None or val > res:
                            res = val
                    else:
                        if res is None or val < res:
                            res = val

        if is_alice_turn:
            memo_f[segments] = res
        else:
            memo_g[segments] = res
        return res

    # Let's compute f(n) = get_value((n,), True)
    results = []
    for n in range(n_max + 1):
        results.append(get_value((n,), True))
    return results

